<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard | ShopNest</title><link rel="stylesheet" href="style.css"></head><body><?php require __DIR__.'/../layout/header.php'; ?><main class="container cart-page"><div class="page-head"><span class="badge">Admin</span><h1>Admin Dashboard</h1><p>Manage inventory, orders, users, sellers and reports.</p></div><?php if($message): ?><p class="success-message">✓ <?= htmlspecialchars($message) ?></p><?php endif; ?><div class="stats-grid"><div class="stat-card"><strong><?= $report['orders_count'] ?></strong><span>Total Orders</span></div><div class="stat-card"><strong>Tk:<?= number_format($report['sales'],2) ?></strong><span>Total Sales</span></div><div class="stat-card"><strong><?= Product::count($GLOBALS['conn']) ?></strong><span>Products</span></div><div class="stat-card"><strong><?= $users->num_rows ?></strong><span>Customers</span></div></div><section class="panel admin-section"><h2>Manage Inventory</h2><form method="post" class="form-grid"><input type="hidden" name="action" value="product_add"><div class="field"><label>Product Name</label><input name="name" required></div><div class="field"><label>Price</label><input name="price" type="number" step="0.01" required></div><div class="field"><label>Stock</label><input name="stock" type="number" min="0" required></div><div class="field"><label>Seller</label><select name="seller_id" required><?php while($s=$sellerOptions->fetch_assoc()): ?><option value="<?= $s['seller_id'] ?>"><?= htmlspecialchars($s['shop_name']) ?></option><?php endwhile; ?></select></div><div class="field"><label>Category</label><select name="category_id" required><?php while($c=$categoryOptions->fetch_assoc()): ?><option value="<?= $c['category_id'] ?>"><?= htmlspecialchars($c['category_name']) ?></option><?php endwhile; ?></select></div><div class="field" style="grid-column:1/-1"><label>Description</label><textarea name="description"></textarea></div><button class="btn btn-primary">Add Product</button></form><div class="table-wrap"><table><tr><th>Product</th><th>Seller</th><th>Category</th><th>Price</th><th>Stock</th><th>Action</th></tr><?php while($p=$products->fetch_assoc()): ?><tr><td><?= htmlspecialchars($p['name']) ?></td><td><?= htmlspecialchars($p['shop_name']??'-') ?></td><td><?= htmlspecialchars($p['category_name']??'-') ?></td><td>Tk:<?= number_format($p['price'],2) ?></td><td><?= $p['stock'] ?></td><td><form method="post"><input type="hidden" name="action" value="product_delete"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="btn btn-danger">Delete</button></form></td></tr><?php endwhile; ?></table></div></section><section class="panel admin-section"><h2>Manage Orders</h2><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr><?php while($o=$orders->fetch_assoc()): ?><tr><td>#<?= $o['id'] ?></td><td><?= htmlspecialchars($o['customer_name']) ?></td><td>Tk:<?= number_format($o['total'],2) ?></td><td><?= htmlspecialchars($o['status']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?= $o['id'] ?>"><select name="status"><option>pending</option><option>confirmed</option><option>processing</option><option>shipped</option><option>delivered</option><option>cancelled</option></select><button class="btn btn-primary">Save</button></form></td></tr><?php endwhile; ?></table></div></section><section class="panel admin-section"><h2>Manage Sellers</h2><div class="table-wrap"><table><tr><th>Shop</th><th>Email</th><th>Status</th><th>Action</th></tr><?php while($s=$sellers->fetch_assoc()): ?><tr><td><?= htmlspecialchars($s['shop_name']) ?></td><td><?= htmlspecialchars($s['email']) ?></td><td><?= htmlspecialchars($s['status']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="action" value="seller_status"><input type="hidden" name="id" value="<?= $s['seller_id'] ?>"><select name="status"><option>approved</option><option>pending</option><option>rejected</option></select><button class="btn btn-primary">Save</button></form></td></tr><?php endwhile; ?></table></div></section><section class="panel admin-section"><h2>Manage Categories</h2><form method="post" class="inline-form"><input type="hidden" name="action" value="category_add"><input name="category_name" placeholder="New category" required><button class="btn btn-primary">Add Category</button></form><p class="muted-text">Categories are used to classify products.</p></section><section class="panel admin-section"><h2>Manage Users</h2><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Action</th></tr><?php while($u=$users->fetch_assoc()): ?><tr><td><?= htmlspecialchars($u['name']) ?></td><td><?= htmlspecialchars($u['email']) ?></td><td><?= htmlspecialchars($u['phone']) ?></td><td><form method="post"><input type="hidden" name="action" value="user_delete"><input type="hidden" name="id" value="<?= $u['id'] ?>"><button class="btn btn-danger">Delete</button></form></td></tr><?php endwhile; ?></table></div></section></main><?php require __DIR__.'/../layout/footer.php'; ?></body></html>
